import AppKit
import ImageIO
import UniformTypeIdentifiers

enum Clipboard {
    static let byteLimit = 20 * 1024 * 1024
    private static let privateTypes: Set<String> = [
        "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType", "com.agilebits.onepassword",
        "de.petermaurer.TransientPasteboardType"
    ]
    private static let supported: [NSPasteboard.PasteboardType] = [.fileURL, .URL, .string, .rtf, .rtfd, .html, .png, .tiff, .init("public.jpeg")]

    static func read(_ board: NSPasteboard) -> Payload? {
        let revision = board.changeCount
        guard let contents = board.pasteboardItems, !contents.isEmpty,
              contents.allSatisfy({ item in item.types.allSatisfy { !privateTypes.contains($0.rawValue) } }) else { return nil }
        // Finder selections also advertise filenames as text and icons as images.
        // Store one native file reference per item, including on legacy filename pasteboards.
        let hasFiles = contents.contains { $0.types.contains(.fileURL) }
        let legacy = NSPasteboard.PasteboardType("NSFilenamesPboardType")
        if hasFiles || board.types?.contains(legacy) == true {
            var urls = board.readObjects(forClasses: [NSURL.self], options: [.urlReadingFileURLsOnly: true]) as? [URL] ?? []
            if let paths = board.propertyList(forType: legacy) as? [String], paths.count > urls.count,
               paths.allSatisfy({ $0.hasPrefix("/") }) {
                urls = paths.map { URL(fileURLWithPath: $0) }
            }
            guard !urls.isEmpty, urls.allSatisfy(\.isFileURL), board.changeCount == revision else { return nil }
            let files = FileClips.capture(urls)
            return files.size <= byteLimit ? files : nil
        }
        var bytes = 0
        var items = [[String: Data]]()
        for item in contents {
            var values = [String: Data]()
            for type in supported where item.types.contains(type) {
                guard let data = item.data(forType: type) else { continue }
                bytes += data.count
                guard bytes <= byteLimit else { return nil }
                values[type.rawValue] = data
            }
            guard !values.isEmpty else { return nil }
            items.append(values)
        }
        return revision == board.changeCount ? Payload(items: items) : nil
    }

    static func write(_ payload: Payload, to board: NSPasteboard) -> Bool {
        // This path also handles clips captured by earlier versions with a text fallback.
        if payload.items.contains(where: { $0[NSPasteboard.PasteboardType.fileURL.rawValue] != nil }) {
            var files = payload
            do {
                try FileClips.restore(&files, to: board, authorize: { _ in nil })
                return true
            } catch { return false }
        }
        let objects = payload.items.map { formats in
            let item = NSPasteboardItem()
            for (type, data) in formats { item.setData(data, forType: .init(type)) }
            return item
        }
        board.clearContents()
        return board.writeObjects(objects)
    }

    static func describe(_ payload: Payload, source: String, digest: String, id: UUID = UUID()) -> Clip {
        let first = payload.items[0]
        func string(_ type: NSPasteboard.PasteboardType) -> String? {
            first[type.rawValue].flatMap { String(data: $0, encoding: .utf8) }
        }
        var kind = ClipKind.text
        var preview = string(.string) ?? ""
        var detail = ""
        var thumbnail: Data?
        if first[NSPasteboard.PasteboardType.fileURL.rawValue] != nil {
            kind = .files
            let names = payload.items.compactMap { item in
                item[NSPasteboard.PasteboardType.fileURL.rawValue].flatMap { URL(dataRepresentation: $0, relativeTo: nil)?.lastPathComponent }
            }
            preview = names.joined(separator: "\n")
            detail = names.count == 1 ? "1 file" : "\(names.count) files"
        } else if let bytes = first["public.png"] ?? first["public.jpeg"] ?? first["public.tiff"],
                  let image = CGImageSourceCreateWithData(bytes as CFData, nil) {
            kind = .image
            preview = "Image"
            let info = CGImageSourceCopyPropertiesAtIndex(image, 0, nil) as? [CFString: Any]
            if let w = info?[kCGImagePropertyPixelWidth], let h = info?[kCGImagePropertyPixelHeight] {
                detail = "\(w) × \(h)"
            }
            let options: [CFString: Any] = [kCGImageSourceCreateThumbnailFromImageAlways: true, kCGImageSourceThumbnailMaxPixelSize: 480, kCGImageSourceCreateThumbnailWithTransform: true]
            if let thumb = CGImageSourceCreateThumbnailAtIndex(image, 0, options as CFDictionary) {
                thumbnail = NSBitmapImageRep(cgImage: thumb).representation(using: .jpeg, properties: [.compressionFactor: 0.76])
            }
        } else {
            if preview.isEmpty {
                preview = string(.URL) ?? ""
                if preview.isEmpty, let data = first[NSPasteboard.PasteboardType.rtf.rawValue] {
                    preview = NSAttributedString(rtf: data, documentAttributes: nil)?.string ?? ""
                }
            }
            let trimmed = preview.trimmingCharacters(in: .whitespacesAndNewlines)
            if let url = URL(string: trimmed), ["http", "https"].contains(url.scheme?.lowercased() ?? ""), let host = url.host, !trimmed.contains(where: \.isWhitespace) {
                kind = .link
                detail = host
            } else if trimmed.range(of: "^#([0-9a-fA-F]{3}|[0-9a-fA-F]{6})$", options: .regularExpression) != nil {
                kind = .color
                preview = trimmed.uppercased()
                detail = "HEX"
            } else {
                let count = preview.count
                if ["func ", "import ", "const ", "let ", "def ", "SELECT ", "class ", "#!/"].contains(where: { trimmed.hasPrefix($0) }) { kind = .code }
                detail = "\(count.formatted()) character\(count == 1 ? "" : "s")"
                if preview.isEmpty { preview = "Formatted content"; detail = "Rich text" }
            }
        }
        return Clip(id: id, digest: digest, date: .now, source: source, kind: kind, preview: String(preview.prefix(32_768)), detail: detail, thumbnail: thumbnail, size: payload.size)
    }
}
